insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Alteração de local especialmente protegido: alterar, sem licença da autoridade competente, o aspecto de local especialmente protegido por lei. Pena: detenção de 1 mês a 1 ano, ou multa.', '["Alterar o aspecto de local especialmente protegido por lei.","Sem licença da autoridade competente.","Detenção de 1 mês a 1 ano, ou multa."]'::jsonb, '["A proteção deve decorrer de LEI."]'::jsonb, 'Reformar a fachada de um local protegido sem licença da autoridade.', '["Assertiva que dispensa a ausência de licença da autoridade erra: é elemento do tipo."]'::jsonb, '[]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
