insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraude no comércio: enganar, no exercício de atividade comercial, o adquirente ou consumidor, vendendo como verdadeira ou perfeita mercadoria falsificada ou deteriorada, ou entregando uma mercadoria por outra. Pena: detenção de 6 meses a 2 anos, ou multa. Também quem altera, em obra encomendada, a qualidade ou o peso de metal, substitui pedra verdadeira por falsa ou menos valiosa, vende pedra falsa por verdadeira ou como precioso metal de outra qualidade: reclusão de 1 a 5 anos e multa. Aplica-se o art. 155, §2º.', '["Enganar o adquirente ou consumidor no exercício de atividade comercial.","I – vender como verdadeira mercadoria falsificada ou deteriorada; II – entregar mercadoria por outra.","Detenção de 6 meses a 2 anos, ou multa.","§1º: fraudes com metais e pedras: reclusão de 1 a 5 anos e multa.","§2º: privilégio do art. 155, §2º."]'::jsonb, '["Exige atividade COMERCIAL.","As fraudes com metais e pedras têm pena de reclusão."]'::jsonb, 'Lojista vende como original uma mercadoria falsificada.', '["Assertiva que aplica o art. 175 a quem não exerce atividade comercial erra."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-175'
