insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Outras fraudes: tomar refeição em restaurante, alojar-se em hotel ou utilizar-se de meio de transporte sem dispor de recursos para efetuar o pagamento. Pena: detenção de 15 dias a 2 meses, ou multa. Somente se procede mediante representação, e o juiz pode, conforme as circunstâncias, deixar de aplicar a pena.', '["Consumir refeição, hospedagem ou transporte sem recursos para pagar.","Detenção de 15 dias a 2 meses, ou multa.","Ação condicionada à representação.","O juiz pode deixar de aplicar a pena."]'::jsonb, '["Hipótese conhecida como ''calote''; ação condicionada à representação."]'::jsonb, 'Pessoa almoça em restaurante sabendo que não tem dinheiro para pagar.', '["Assertiva que torna incondicionada a ação do art. 176 erra: exige representação."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-176'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraudes e abusos na fundação ou administração de sociedade por ações: promover a fundação de sociedade por ações fazendo, em prospecto ou comunicação ao público ou à assembleia, afirmação falsa sobre a constituição da sociedade, ou ocultando fraudulentamente fato a ela relativo. Pena: reclusão de 1 a 4 anos e multa, se o fato não constitui crime contra a economia popular. Na mesma pena incorrem diretor, gerente ou fiscal que faz afirmação falsa sobre as condições econômicas da sociedade, promove falsa cotação das ações, toma empréstimo à sociedade ou usa bens sociais sem autorização da assembleia, compra ou vende ações da própria sociedade fora dos casos permitidos, ou aceita em penhor ou caução ações da própria sociedade como garantia de crédito social.', '["Falsa afirmação ou ocultação fraudulenta na fundação de sociedade por ações.","Pena: reclusão de 1 a 4 anos e multa, se não for crime contra a economia popular.","§1º, I a V: condutas de diretor, gerente ou fiscal (afirmação falsa; falsa cotação; uso de bens da sociedade; negociação de ações próprias; aceitar ações próprias em penhor)."]'::jsonb, '["Subsidiário ao crime contra a economia popular (ressalva expressa)."]'::jsonb, 'O diretor promove falsa cotação das ações da companhia para atrair investidores.', '["Assertiva que aplica o art. 177 mesmo quando o fato constitui crime contra a economia popular erra: a ressalva afasta o tipo."]'::jsonb, '[{"termo":"Prospecto","significado":"Documento de oferta pública de valores mobiliários."}]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-177'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Emissão irregular de conhecimento de depósito ou warrant: emitir conhecimento de depósito ou warrant em desacordo com disposição legal. Pena: reclusão de 1 a 4 anos e multa.', '["Emitir conhecimento de depósito ou warrant em desacordo com a lei.","Reclusão de 1 a 4 anos e multa."]'::jsonb, '["Crime próprio de quem emite esses títulos (armazéns gerais)."]'::jsonb, 'Armazém emite warrant sem a mercadoria correspondente.', '["Assertiva que prevê detenção para o art. 178 erra: a pena é de reclusão."]'::jsonb, '[{"termo":"Warrant","significado":"Título que representa mercadoria depositada e permite sua oneração como garantia."}]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-178'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraude à execução: fraudar execução, alienando, desviando, destruindo ou danificando bens, ou simulando dívidas. Pena: detenção de 6 meses a 2 anos, ou multa. Somente se procede mediante queixa.', '["Alienar, desviar, destruir ou danificar bens, ou simular dívidas, para fraudar execução.","Detenção de 6 meses a 2 anos, ou multa.","Ação penal privada (queixa)."]'::jsonb, '["Ação penal por QUEIXA (privada)."]'::jsonb, 'O devedor, já sendo executado, vende seu único imóvel a um parente por preço simbólico para frustrar a cobrança.', '["Assertiva que torna pública incondicionada a ação na fraude à execução erra: é por queixa."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-179'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Receptação: adquirir, receber, transportar, conduzir ou ocultar, em proveito próprio ou alheio, coisa que sabe ser produto de crime, ou influir para que terceiro, de boa-fé, a adquira, receba ou oculte. Pena: reclusão de 2 a 6 anos e multa (texto atual). Receptação qualificada (§1º): no exercício de atividade comercial ou industrial, coisa que deve saber ser produto de crime (reclusão de 3 a 8 anos e multa), e o §2º equipara à atividade comercial qualquer forma de comércio irregular ou clandestino, inclusive em residência. Receptação culposa (§3º): adquirir ou receber coisa que, por sua natureza, pela desproporção entre valor e preço ou pela condição de quem a oferece, deve presumir-se obtida por meio criminoso: detenção de 1 mês a 1 ano, ou multa, ou ambas. A receptação é punível ainda que desconhecido ou isento de pena o autor do crime anterior (§4º). Bens de entes públicos: pena em dobro (§6º); fios, cabos e equipamentos de energia, telefonia, dados ou cargas ferroviárias ou metroviárias: em dobro (§7º).', '["Caput: sabe ser produto de crime; reclusão de 2 a 6 anos e multa.","§1º: qualificada (atividade comercial ou industrial; ''deve saber''): reclusão de 3 a 8 anos e multa.","§2º: comércio irregular ou clandestino, inclusive em residência, equipara-se à atividade comercial.","§3º: culposa (deve presumir-se obtida por meio criminoso): detenção de 1 mês a 1 ano, ou multa, ou ambas.","§4º: punível ainda que o autor do crime anterior seja desconhecido ou isento de pena.","§6º: bens da União, Estados, DF, Municípios e entes públicos: pena em dobro.","§7º: fios, cabos, equipamentos e cargas citados: pena em dobro."]'::jsonb, '["Caput exige DOLO DIRETO (''sabe ser produto de crime''); no §1º basta ''deve saber''.","Receptação CULPOSA: §3º, com pena de detenção.","A receptação é crime AUTÔNOMO: independe da punição do autor do crime antecedente (§4º)."]'::jsonb, 'Quem compra, por preço muito abaixo do mercado, celular oferecido por desconhecido na rua pode responder por receptação culposa (§3º).', '["Assertiva que exige a condenação do autor do crime anterior para punir a receptação erra: o §4º a dispensa."]'::jsonb, '[{"termo":"Receptação","significado":"Lidar com coisa que se sabe (ou deve saber) ser produto de crime."}]'::jsonb, '["Art. 180-A","Art. 155"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-180'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Receptação de animais: adquirir, receber, transportar, conduzir, ocultar, ter em depósito ou vender, com a finalidade de produção ou comercialização, semovente domesticável de produção, ainda que abatido ou dividido em partes, ou animal doméstico, que sabe ou deve saber ser produto de crime. Pena: reclusão de 3 a 8 anos e multa (texto atual).', '["Objeto: semovente domesticável de produção (mesmo abatido ou dividido em partes) ou animal doméstico.","Finalidade de produção ou comercialização.","Sabe ou deve saber que é produto de crime.","Reclusão de 3 a 8 anos e multa."]'::jsonb, '["Basta ''sabe ou deve saber''."]'::jsonb, 'Frigorífico recebe gado abatido de origem criminosa para comercializar.', '["Assertiva que exige finalidade de lucro direto para o crime erra: o tipo fala em finalidade de produção ou comercialização."]'::jsonb, '[{"termo":"Semovente","significado":"Animal que se move por si, como o gado."}]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-180-a'
