insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Imunidades absolutas: é isento de pena quem comete qualquer dos crimes contra o patrimônio em prejuízo do cônjuge, na constância da sociedade conjugal, ou de ascendente ou descendente, seja o parentesco legítimo ou ilegítimo, civil ou natural. O texto traz a indicação ''Vide Lei nº 10.741/2003'' (Estatuto da Pessoa Idosa).', '["Isento de pena: crime patrimonial contra o cônjuge na constância da sociedade conjugal.","Isento de pena: contra ascendente ou descendente (qualquer parentesco)."]'::jsonb, '["É escusa absolutória (imunidade absoluta); o texto remete ao Estatuto da Pessoa Idosa para conferir exceções.","Não vale se o crime é roubo ou extorsão, ou com grave ameaça ou violência (art. 183)."]'::jsonb, 'Filho que furta objeto do pai é isento de pena (salvo exceções legais).', '["Assertiva que aplica a imunidade do art. 181 ao roubo praticado contra o pai erra: o art. 183 a afasta quando há violência ou grave ameaça."]'::jsonb, '[{"termo":"Escusa absolutória","significado":"Causa que isenta o agente de pena por razões de política criminal, mesmo havendo crime."}]'::jsonb, '["Art. 182","Art. 183"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-181'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Imunidades relativas: somente se procede mediante representação se o crime patrimonial é cometido em prejuízo de cônjuge desquitado ou judicialmente separado; de irmão, legítimo ou ilegítimo; ou de tio ou sobrinho com quem o agente coabita. O texto remete ao Estatuto da Pessoa Idosa.', '["Ação condicionada à representação: cônjuge separado; irmão; tio ou sobrinho que coabita com o agente."]'::jsonb, '["Imunidade RELATIVA: há crime, mas a ação depende de representação."]'::jsonb, 'Furto contra o irmão: o processo depende de representação da vítima.', '["Assertiva que isenta de pena o furto praticado contra o irmão erra: a hipótese é de ação condicionada, não de isenção."]'::jsonb, '[]'::jsonb, '["Arts. 181 e 183"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-182'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

